class Created:
    def __eq__(self, other):
        return True
print(Created.__hash__ is None)
class Patched:
    pass
old_hash = Patched.__hash__
Patched.__eq__ = lambda self, other: True
print(Patched.__hash__ is old_hash)

def f(a):
    return a
def g(a, /, **kwargs):
    return a, kwargs
try:
    f(1, **{"a": 2})
except TypeError:
    print("TypeError")
print(g(1, **{"a": 2}))

def f(a, /, b=1, *args, c, d=2, **kwargs):
    print(a, b, args, c, d, kwargs)
f(10, 20, 30, c=40, a=50)
